insert into public.course_subjects (id, title, roman, description, sort_order)
values
  ($q$restaurant$q$, $q$Order at a Restaurant$q$, $q$ráan-aa-hǎan$q$, $q$Real Thai ordered straight from a restaurant menu — every word and sentence here is copied from Essential Thai by James Higbie, not invented.$q$, 2)
insert into public.course_lessons (id, subject_id, sort_order, title, steps)
values
  ($q$r01$q$, $q$restaurant$q$, 0, $q$Asking for a menu, and what they have$q$, $j$[{"id":"rule-1","type":"rule","title":"Thai tones","body":"Thai has five tones: mid, low, falling, high, and rising. The same syllable changes meaning with its tone — mái (high) is \"wood\", mài (low) is \"new\", and mǎi (rising) is \"silk\". Getting the tone right changes the word.","source":"Essential Thai (Higbie), pp.8-9"},{"id":"wi-2","type":"wordIntro","word":{"thai":"ขอ","roman":"khɔ̌ɔ","english":"may I have / please give me"},"source":"Essential Thai (Higbie), p.116"},{"id":"wi-3","type":"wordIntro","word":{"thai":"เมนู","roman":"menuu","english":"menu"},"source":"Essential Thai (Higbie), p.118"},{"id":"wi-4","type":"wordIntro","word":{"thai":"ด้วย","roman":"dûai","english":"please / also"},"source":"Essential Thai (Higbie), p.116"},{"id":"mc-5","type":"translationChoice","thai":"ขอเมนูด้วย","roman":"khɔ̌ɔ menuu dûai","options":[{"text":"I like it very much.","correct":false},{"text":"May I have a menu?","correct":true},{"text":"What do you have?","correct":false},{"text":"Check, please.","correct":false}],"source":"Essential Thai (Higbie), p.118","parts":["ขอ","เมนู","ด้วย"]},{"id":"so-6","type":"sentenceOrder","prompt":"May I have a menu?","tileUnit":"word","words":{"a":{"roman":"khɔ̌ɔ","thai":"ขอ"},"b":{"roman":"menuu","thai":"เมนู"},"c":{"roman":"dûai","thai":"ด้วย"}},"poolOrder":["c","b","a"],"correctOrder":["a","b","c"],"source":"Essential Thai (Higbie), p.118"},{"id":"sp-7","type":"speak","thai":"ขอเมนูด้วย","roman":"khɔ̌ɔ menuu dûai","meaning":"May I have a menu?","source":"Essential Thai (Higbie), p.118","parts":["ขอ","เมนู","ด้วย"]},{"id":"mc-13","type":"translationChoice","thai":"ขอเมนูด้วย","roman":"khɔ̌ɔ menuu dûai","options":[{"text":"How much is it?","correct":false},{"text":"May I have a menu?","correct":true},{"text":"What do you have?","correct":false},{"text":"Check, please.","correct":false}],"source":"Essential Thai (Higbie), p.118","parts":["ขอ","เมนู","ด้วย"]},{"id":"wi-8","type":"wordIntro","word":{"thai":"มี","roman":"mii","english":"have / there is"},"source":"Essential Thai (Higbie), p.118"},{"id":"wi-9","type":"wordIntro","word":{"thai":"อะไร","roman":"à-rai","english":"what"},"source":"Essential Thai (Higbie), p.118"},{"id":"wi-10","type":"wordIntro","word":{"thai":"บ้าง","roman":"bâang","english":"some / any"},"source":"Essential Thai (Higbie), p.118"},{"id":"mc-11","type":"translationChoice","thai":"มีอะไรบ้าง","roman":"mii à-rai bâang","options":[{"text":"May I have a menu?","correct":false},{"text":"It is very good.","correct":false},{"text":"What do you have?","correct":true},{"text":"Check, please.","correct":false}],"source":"Essential Thai (Higbie), p.118","parts":["มี","อะไร","บ้าง"]},{"id":"so-12","type":"sentenceOrder","prompt":"What do you have?","tileUnit":"word","words":{"a":{"roman":"mii","thai":"มี"},"b":{"roman":"à-rai","thai":"อะไร"},"c":{"roman":"bâang","thai":"บ้าง"},"x0":{"thai":"เมนู","roman":"menuu"},"x1":{"thai":"ขอ","roman":"khɔ̌ɔ"}},"poolOrder":["x0","a","c","x1","b"],"correctOrder":["a","b","c"],"source":"Essential Thai (Higbie), p.118"},{"id":"sp-14","type":"speak","thai":"มีอะไรบ้าง","roman":"mii à-rai bâang","meaning":"What do you have?","source":"Essential Thai (Higbie), p.118","parts":["มี","อะไร","บ้าง"]},{"id":"match-15","type":"match","pairs":[{"thai":"ขอ","roman":"khɔ̌ɔ","english":"may I have / please give me"},{"thai":"เมนู","roman":"menuu","english":"menu"},{"thai":"ด้วย","roman":"dûai","english":"please / also"},{"thai":"มี","roman":"mii","english":"have / there is"},{"thai":"อะไร","roman":"à-rai","english":"what"},{"thai":"บ้าง","roman":"bâang","english":"some / any"}],"source":"Essential Thai (Higbie), p.116"}]$j$::jsonb),
  ($q$r02$q$, $q$restaurant$q$, 1, $q$Numbers, plates, and water$q$, $j$[{"id":"rule-16","type":"rule","title":"Counting in Thai","body":"Numbers in Thai go before the container or classifier word when they are more than one — but \"one\" can go either before or after it. Learn one to ten and you can build almost any number.","source":"Essential Thai (Higbie), p.17"},{"id":"wi-17","type":"wordIntro","word":{"thai":"หนึ่ง","roman":"nɯ̀ng","english":"one"},"source":"Essential Thai (Higbie), p.17"},{"id":"mc-20","type":"translationChoice","thai":"หนึ่ง","roman":"nɯ̀ng","options":[{"text":"One","correct":true},{"text":"Three","correct":false},{"text":"Menu","correct":false},{"text":"Two","correct":false}],"source":"Essential Thai (Higbie), p.17","parts":["หนึ่ง"]},{"id":"sp-24","type":"speak","thai":"หนึ่ง","roman":"nɯ̀ng","meaning":"one","source":"Essential Thai (Higbie), p.17","parts":["หนึ่ง"]},{"id":"wi-18","type":"wordIntro","word":{"thai":"สอง","roman":"sɔ̌ɔng","english":"two"},"source":"Essential Thai (Higbie), p.17"},{"id":"mc-21","type":"translationChoice","thai":"สอง","roman":"sɔ̌ɔng","options":[{"text":"Three","correct":false},{"text":"What do you have?","correct":false},{"text":"Two","correct":true},{"text":"One","correct":false}],"source":"Essential Thai (Higbie), p.17","parts":["สอง"]},{"id":"sp-25","type":"speak","thai":"สอง","roman":"sɔ̌ɔng","meaning":"two","source":"Essential Thai (Higbie), p.17","parts":["สอง"]},{"id":"wi-19","type":"wordIntro","word":{"thai":"สาม","roman":"sǎam","english":"three"},"source":"Essential Thai (Higbie), p.17"},{"id":"mc-22","type":"translationChoice","thai":"สาม","roman":"sǎam","options":[{"text":"Three","correct":true},{"text":"One","correct":false},{"text":"Please","correct":false},{"text":"Two","correct":false}],"source":"Essential Thai (Higbie), p.17","parts":["สาม"]},{"id":"so-23","type":"sentenceOrder","prompt":"One, two, three","tileUnit":"word","words":{"a":{"roman":"nɯ̀ng","thai":"หนึ่ง"},"b":{"roman":"sɔ̌ɔng","thai":"สอง"},"c":{"roman":"sǎam","thai":"สาม"},"x0":{"thai":"มี","roman":"mii"},"x1":{"thai":"ด้วย","roman":"dûai"}},"poolOrder":["x1","c","a","x0","b"],"correctOrder":["a","b","c"],"source":"Essential Thai (Higbie), p.17"},{"id":"wi-26","type":"wordIntro","word":{"thai":"จาน","roman":"jaan","english":"plate"},"source":"Essential Thai (Higbie), p.116"},{"id":"wi-27","type":"wordIntro","word":{"thai":"แก้ว","roman":"gɛ̂ɛo","english":"glass"},"source":"Essential Thai (Higbie), p.116"},{"id":"wi-28","type":"wordIntro","word":{"thai":"น้ำ","roman":"náam","english":"water"},"source":"Essential Thai (Higbie), p.120"},{"id":"mc-30","type":"translationChoice","thai":"ขอน้ำด้วย","roman":"khɔ̌ɔ náam dûai","options":[{"text":"May I have some water?","correct":true},{"text":"What do you have?","correct":false},{"text":"May I have a menu?","correct":false},{"text":"One, please.","correct":false}],"source":"Essential Thai (Higbie), p.120","parts":["ขอ","น้ำ","ด้วย"]},{"id":"wi-29","type":"wordIntro","word":{"thai":"กับ","roman":"gàp","english":"and / with"},"source":"Essential Thai (Higbie), general reference (connecting words)"},{"id":"so-31","type":"sentenceOrder","prompt":"I'd like a plate and a glass.","tileUnit":"word","words":{"a":{"roman":"khɔ̌ɔ","thai":"ขอ"},"b":{"roman":"jaan","thai":"จาน"},"c":{"roman":"gàp","thai":"กับ"},"d":{"roman":"gɛ̂ɛo","thai":"แก้ว"},"x0":{"thai":"สาม","roman":"sǎam"},"x1":{"thai":"น้ำ","roman":"náam"}},"poolOrder":["d","x1","x0","c","a","b"],"correctOrder":["a","b","c","d"],"source":"Essential Thai (Higbie), p.120"},{"id":"mc-32","type":"translationChoice","thai":"ขอจานกับแก้วด้วย","roman":"khɔ̌ɔ jaan gàp gɛ̂ɛo dûai","options":[{"text":"What do you have?","correct":false},{"text":"Two glasses, please.","correct":false},{"text":"I'd like a plate and a glass.","correct":true},{"text":"May I have some water?","correct":false}],"source":"Essential Thai (Higbie), p.116","parts":["ขอ","จาน","กับ","แก้ว","ด้วย"]},{"id":"sp-33","type":"speak","thai":"ขอน้ำกับจานด้วย","roman":"khɔ̌ɔ náam gàp jaan dûai","meaning":"May I have water and a plate?","source":"Essential Thai (Higbie), p.120","parts":["ขอ","น้ำ","กับ","จาน","ด้วย"]},{"id":"match-34","type":"match","pairs":[{"thai":"หนึ่ง","roman":"nɯ̀ng","english":"one"},{"thai":"สอง","roman":"sɔ̌ɔng","english":"two"},{"thai":"สาม","roman":"sǎam","english":"three"},{"thai":"จาน","roman":"jaan","english":"plate"},{"thai":"แก้ว","roman":"gɛ̂ɛo","english":"glass"},{"thai":"น้ำ","roman":"náam","english":"water"},{"thai":"กับ","roman":"gàp","english":"and / with"}],"source":"Essential Thai (Higbie), p.17"}]$j$::jsonb),
  ($q$r03$q$, $q$restaurant$q$, 2, $q$Ordering fried rice, and more$q$, $j$[{"id":"wi-35","type":"wordIntro","word":{"thai":"ข้าวผัด","roman":"khâao-phàt","english":"fried rice"},"source":"Essential Thai (Higbie), p.116"},{"id":"wi-36","type":"wordIntro","word":{"thai":"ไก่","roman":"gài","english":"chicken"},"source":"Essential Thai (Higbie), p.116"},{"id":"mc-161","type":"translationChoice","thai":"ขอข้าวผัดไก่หนึ่งจาน","roman":"khɔ̌ɔ khâao-phàt gài nɯ̀ng jaan","options":[{"text":"One more plate, please.","correct":false},{"text":"pork fried rice","correct":false},{"text":"One chicken fried rice, please.","correct":true},{"text":"with chicken","correct":false}],"source":"Essential Thai (Higbie), p.116","parts":["ขอ","ข้าวผัด","ไก่","หนึ่ง","จาน"]},{"id":"sp-166","type":"speak","thai":"ขอข้าวผัดไก่หนึ่งจาน","roman":"khɔ̌ɔ khâao-phàt gài nɯ̀ng jaan","meaning":"One chicken fried rice, please.","source":"Essential Thai (Higbie), p.116","parts":["ขอ","ข้าวผัด","ไก่","หนึ่ง","จาน"]},{"id":"wi-37","type":"wordIntro","word":{"thai":"ใส่","roman":"sài","english":"put / with"},"source":"Essential Thai (Higbie), p.116"},{"id":"so-162","type":"sentenceOrder","prompt":"with chicken","tileUnit":"word","words":{"a":{"roman":"sài","thai":"ใส่"},"b":{"roman":"gài","thai":"ไก่"},"x0":{"thai":"แก้ว","roman":"gɛ̂ɛo"},"x1":{"thai":"อะไร","roman":"à-rai"}},"poolOrder":["x1","b","a","x0"],"correctOrder":["a","b"],"source":"Essential Thai (Higbie), p.116"},{"id":"wi-43","type":"wordIntro","word":{"thai":"อีก","roman":"ìik","english":"more / another"},"source":"Essential Thai (Higbie), p.117"},{"id":"sp-164","type":"speak","thai":"ขออีกจานหนึ่ง","roman":"khɔ̌ɔ ìik jaan nɯ̀ng","meaning":"One more plate, please.","source":"Essential Thai (Higbie), p.116","parts":["ขอ","อีก","จาน","หนึ่ง"]},{"id":"wi-44","type":"wordIntro","word":{"thai":"ขวด","roman":"khùat","english":"bottle"},"source":"Essential Thai (Higbie), p.117"},{"id":"so-165","type":"sentenceOrder","prompt":"Another bottle of water, please.","tileUnit":"word","words":{"a":{"roman":"khɔ̌ɔ","thai":"ขอ"},"b":{"roman":"náam","thai":"น้ำ"},"c":{"roman":"ìik","thai":"อีก"},"d":{"roman":"khùat","thai":"ขวด"},"x0":{"thai":"ใส่","roman":"sài"},"x1":{"thai":"ข้าวผัด","roman":"khâao-phàt"}},"poolOrder":["x0","d","c","b","x1","a"],"correctOrder":["a","b","c","d"],"source":"Essential Thai (Higbie), p.116"},{"id":"rp-167","type":"reply","context":[{"speaker":"M","thai":"ใส่อะไร","parts":["ใส่","อะไร"],"roman":"sài à-rai","english":"With what?"}],"replySpeaker":"F","thai":"ใส่ไก่","roman":"sài gài","english":"With chicken.","options":[{"thai":"ขวด","roman":"khùat","correct":false},{"thai":"ขอเมนูด้วย","roman":"khɔ̌ɔ menuu dûai","correct":false},{"thai":"ใส่ไก่","roman":"sài gài","correct":true}],"source":"Essential Thai (Higbie), p.116","parts":["ใส่","ไก่"]},{"id":"wi-45","type":"wordIntro","word":{"thai":"หมู","roman":"mǔu","english":"pork"},"source":"Essential Thai (Higbie), p.116"},{"id":"mc-163","type":"translationChoice","thai":"ข้าวผัดหมู","roman":"khâao-phàt mǔu","options":[{"text":"One chicken fried rice, please.","correct":false},{"text":"with chicken","correct":false},{"text":"pork fried rice","correct":true},{"text":"One more plate, please.","correct":false}],"source":"Essential Thai (Higbie), p.116","parts":["ข้าวผัด","หมู"]},{"id":"match-168","type":"match","pairs":[{"thai":"ข้าวผัด","roman":"khâao-phàt","english":"fried rice"},{"thai":"ไก่","roman":"gài","english":"chicken"},{"thai":"ใส่","roman":"sài","english":"put / with"},{"thai":"อีก","roman":"ìik","english":"more / another"},{"thai":"ขวด","roman":"khùat","english":"bottle"},{"thai":"หมู","roman":"mǔu","english":"pork"}],"source":"Essential Thai (Higbie), p.116"}]$j$::jsonb),
  ($q$r04$q$, $q$restaurant$q$, 3, $q$With, without, and spicy$q$, $j$[{"id":"wi-52","type":"wordIntro","word":{"thai":"ไม่","roman":"mâi","english":"not"},"source":"Essential Thai (Higbie), p.117"},{"id":"wi-53","type":"wordIntro","word":{"thai":"เนื้อ","roman":"nɯ́a","english":"beef"},"source":"Essential Thai (Higbie), p.117"},{"id":"sp-172","type":"speak","thai":"ไม่ใส่เนื้อ","roman":"mâi sài nɯ́a","meaning":"No beef, please.","source":"Essential Thai (Higbie), p.117","parts":["ไม่","ใส่","เนื้อ"]},{"id":"wi-54","type":"wordIntro","word":{"thai":"น้ำตาล","roman":"náam-taan","english":"sugar"},"source":"Essential Thai (Higbie), p.117"},{"id":"mc-171","type":"translationChoice","thai":"ใส่น้ำตาล","roman":"sài náam-taan","options":[{"text":"No chili, please.","correct":false},{"text":"Not spicy at all.","correct":false},{"text":"with sugar","correct":true},{"text":"No beef, please.","correct":false}],"source":"Essential Thai (Higbie), p.117","parts":["ใส่","น้ำตาล"]},{"id":"wi-60","type":"wordIntro","word":{"thai":"เผ็ด","roman":"phèt","english":"spicy / hot"},"source":"Essential Thai (Higbie), p.117"},{"id":"so-173","type":"sentenceOrder","prompt":"fried rice, not spicy","tileUnit":"word","words":{"a":{"roman":"khâao-phàt","thai":"ข้าวผัด"},"b":{"roman":"mâi","thai":"ไม่"},"c":{"roman":"phèt","thai":"เผ็ด"},"x0":{"thai":"สอง","roman":"sɔ̌ɔng"},"x1":{"thai":"จาน","roman":"jaan"}},"poolOrder":["c","x0","x1","b","a"],"correctOrder":["a","b","c"],"source":"Essential Thai (Higbie), p.117"},{"id":"wi-61","type":"wordIntro","word":{"thai":"พริก","roman":"phrík","english":"chili pepper"},"source":"Essential Thai (Higbie), p.117"},{"id":"mc-169","type":"translationChoice","thai":"ไม่ใส่พริก","roman":"mâi sài phrík","options":[{"text":"No chili, please.","correct":true},{"text":"with sugar","correct":false},{"text":"Not spicy at all.","correct":false},{"text":"No beef, please.","correct":false}],"source":"Essential Thai (Higbie), p.117","parts":["ไม่","ใส่","พริก"]},{"id":"s