  ($q$restaurant-dlg$q$, $q$restaurant$q$, 11, $q$Ordering dinner$q$, $j${"kind":"dialogue","scene":"Two friends order food, skip the spice, and ask for the check.","lines":[{"speaker":"A","thai":"ขอเมนูด้วยค่ะ","roman":"khɔ̌ɔ menuu dûai khâ","english":"May I have a menu?"},{"speaker":"B","thai":"ขอข้าวผัดไก่หนึ่งจานครับ","roman":"khɔ̌ɔ khâao-phàt gài nɯ̀ng jaan khráp","english":"I'd like one plate of fried rice with chicken."},{"speaker":"A","thai":"ไม่ใส่พริก ไม่เผ็ดเลยนะคะ","roman":"mâi sài phrík, mâi phèt loei ná khá","english":"No chili — not spicy at all."},{"speaker":"B","thai":"ขอเช็คบิลด้วยครับ","roman":"khɔ̌ɔ chék-bin dûai khráp","english":"Check, please."}],"steps":[{"type":"intro"},{"type":"comprehension","lineIndex":0,"options":[{"text":"May I have a menu?","correct":true},{"text":"What do you have?","correct":false},{"text":"Check, please.","correct":false},{"text":"Not spicy at all.","correct":false}]},{"type":"comprehension","lineIndex":2,"options":[{"text":"No chili — not spicy at all.","correct":true},{"text":"May I have a menu?","correct":false},{"text":"I'd like one plate of fried rice with chicken.","correct":false},{"text":"Check, please.","correct":false}]},{"type":"translate","lineIndex":1,"options":[{"text":"I'd like one plate of fried rice with chicken.","correct":true},{"text":"May I have a menu?","correct":false},{"text":"Check, please.","correct":false},{"text":"Keep the change.","correct":false}]},{"type":"translate","lineIndex":3,"options":[{"text":"Check, please.","correct":true},{"text":"May I have some water?","correct":false},{"text":"What do you have?","correct":false},{"text":"One more plate, please.","correct":false}]},{"type":"blank","lineIndex":2,"before":"mâi sài","after":", mâi phèt loei ná khá","options":[{"text":"phrík","correct":true},{"text":"nɯ́a","correct":false},{"text":"khài","correct":false},{"text":"náam-taan","correct":false}]},{"type":"speak","lineIndex":1},{"type":"speak","lineIndex":3}]}$j$::jsonb)
