delete from public.course_lessons where subject_id = $q$restaurant$q$ and id not in ($q$r01$q$, $q$r02$q$, $q$r03$q$, $q$r04$q$, $q$r05$q$, $q$r06$q$, $q$r07$q$, $q$r08$q$, $q$r09$q$, $q$r10$q$, $q$restaurant-quiz$q$, $q$restaurant-dlg$q$);

